const $=id=>document.getElementById(id);
// Original curriculum: expected results are checked after real Python execution.
const lessons=[
['Hello, explorer!','Print your first message','Python is a language for giving computers instructions. <code>print()</code> displays a message. Put words inside matching quotation marks.',`print("Hello, world!")`,'Print Hello, explorer! on its own line.','Change the words between the quotation marks.',`print("Hello, explorer!")`,'Hello, explorer!'],
['A tiny postcard','Make a message in two lines','Python runs instructions from top to bottom. Each <code>print()</code> starts a new line.',`# Write two print statements below\n`,'Print My name is Python on the first line and Let’s explore! on the second. Use a straight apostrophe in Let\'s.','Use double quotes around a message containing an apostrophe.',`print("My name is Python")\nprint("Let's explore!")`,"My name is Python\nLet's explore!"],
['Pocket calculator','Let Python do the math','Use <code>+</code> to add, <code>-</code> to subtract, <code>*</code> to multiply, and <code>/</code> to divide. Numbers do not need quotation marks.',`print(2 + 3)`,'Print the result of 7 multiplied by 8.','Use the multiplication symbol *.',`print(7 * 8)`,'56'],
['Secret notes','Leave a comment','A comment starts with <code>#</code>. Python ignores it. Comments explain your ideas to future you.',`# This is my secret note\n`,'Keep a comment in your code, then print Ready for adventure!','Add print() below the comment.',`# My adventure starts here\nprint("Ready for adventure!")`,'Ready for adventure!', 'assert "#" in source, "Include a comment beginning with #."'],
['Launch countdown','Your first mini project','Mix text and numbers in separate print statements to build a little rocket launch sequence.',`# Launch your rocket!\n`,'Print 3, 2, 1, and Liftoff! on four separate lines.','Use four print statements.',`print(3)\nprint(2)\nprint(1)\nprint("Liftoff!")`,'3\n2\n1\nLiftoff!'],
['Name your explorer','Store a value','A variable is a name for a value. <code>name = "Pip"</code> stores text. <code>print(name)</code> displays it.',`name = ""\nprint(name)`,'Set name to Pip and print name.','Put Pip between the quotes.',`name = "Pip"\nprint(name)`,'Pip','assert name == "Pip", "Store Pip in the variable name."'],
['Treasure pouch','Add to a number','Variables can hold numbers. <code>coins = coins + 5</code> updates your coins using the old value.',`coins = 10\n# Find 5 more coins\nprint(coins)`,'Start with 10 coins, add 5 to coins, then print coins.','Add coins = coins + 5 before printing.',`coins = 10\ncoins = coins + 5\nprint(coins)`,'15','assert coins == 15, "Update the coins variable to 15."'],
['Say it your way','Build an f-string','An f-string inserts a variable into text: <code>f"Hi, {name}!"</code>. The f before the opening quote matters.',`name = "Pip"\n`,'Use name in an f-string to print Hello, Pip!','Try print(f"Hello, {name}!").',`name = "Pip"\nprint(f"Hello, {name}!")`,'Hello, Pip!', 'assert "{name}" in source and (\'f"\' in source or "f\'" in source), "Use an f-string with {name}."'],
['Sharing snacks','Divide and convert','<code>//</code> divides and rounds down. <code>%</code> gives the remainder. For example, <code>7 % 3</code> is 1.',`snacks = 17\nfriends = 4\n`,'Print how many snacks each friend gets (4), then how many are left (1). Use // and %.','Print snacks // friends, then snacks % friends.',`snacks = 17\nfriends = 4\nprint(snacks // friends)\nprint(snacks % friends)`,'4\n1','assert "//" in source and "%" in source, "Try the // and % operators."'],
['Explorer ID','Make a character card','Combine variables and f-strings to make a character card. You can use more than one variable in an f-string.',`name = "Pip"\nlevel = 1\n`,'Print Explorer: Pip and Level: 1 on separate lines using the variables.','Use print(f"Explorer: {name}") and another f-string for level.',`name = "Pip"\nlevel = 1\nprint(f"Explorer: {name}")\nprint(f"Level: {level}")`,'Explorer: Pip\nLevel: 1'],
['The forest gate','Make a decision','An <code>if</code> runs code only when a condition is true. End the if line with a colon and indent its instructions with four spaces.',`coins = 12\nif coins >= 10:\n    # Write your message here\n    pass`,'If coins is at least 10, print Gate open!.','Replace pass with print("Gate open!").',`coins = 12\nif coins >= 10:\n    print("Gate open!")`,'Gate open!','assert "if " in source, "Use an if statement."'],
['Rain or shine','Choose another path','<code>else:</code> provides an alternative when the if condition is false. True and False are Python’s boolean values.',`raining = False\nif raining:\n    print("Bring a coat")\nelse:\n    pass`,'Use the else branch to print Bring a hat.','Replace pass with a print statement.',`raining = False\nif raining:\n    print("Bring a coat")\nelse:\n    print("Bring a hat")`,'Bring a hat','assert "else:" in source, "Use an else branch."'],
['Three secret doors','Compare with elif','<code>elif</code> checks another condition after an if is false. Python uses <code>==</code> to compare two values; <code>=</code> stores a value.',`door = 2\nif door == 1:\n    print("A sleepy dragon")\n# Add an elif for door 2\n`,'For door 2, print A treasure chest.','Add elif door == 2: with an indented print.',`door = 2\nif door == 1:\n    print("A sleepy dragon")\nelif door == 2:\n    print("A treasure chest")\nelse:\n    print("A friendly frog")`,'A treasure chest','assert "elif " in source, "Try an elif branch."'],
['Both keys','Combine conditions','<code>and</code> needs both conditions to be true. <code>or</code> needs at least one. Use these to make smarter decisions.',`has_map = True\nhas_key = True\n`,'If has_map and has_key are both true, print Adventure unlocked!.','Use if has_map and has_key:.',`has_map = True\nhas_key = True\nif has_map and has_key:\n    print("Adventure unlocked!")`,'Adventure unlocked!','assert " and " in source, "Combine the conditions with and."'],
['Treasure judge','A decision mini project','Write a reward system. Check the biggest reward first so a score of 90 does not get the lower reward.',`score = 85\n# 80 or more: Gold\n# 50 or more: Silver\n# Otherwise: Bronze\n`,'Use if / elif / else to print Gold for 80+, Silver for 50–79, and Bronze otherwise. We check three scores.','Start with if score >= 80:, then elif score >= 50:.',`score = 85\nif score >= 80:\n    print("Gold")\nelif score >= 50:\n    print("Silver")\nelse:\n    print("Bronze")`,'Gold','assert "elif " in source and "else:" in source, "Include all three branches."', [[85,'Gold'],[65,'Silver'],[20,'Bronze']]],
['Echo meadow','Repeat with a loop','A <code>for</code> loop repeats code. <code>range(3)</code> gives 0, 1, 2: three turns. Indent the code you want to repeat.',`for turn in range(3):\n    pass`,'Print Hello! three times using a for loop.','Replace pass with print("Hello!").',`for turn in range(3):\n    print("Hello!")`,'Hello!\nHello!\nHello!','assert "for " in source, "Use a for loop."'],
['Stepping stones','Count with range','<code>range(1, 6)</code> starts at 1 and stops before 6. The loop variable holds each number in turn.',`# Count your steps\n`,'Use a for loop to print 1 through 5, each on its own line.','Try for step in range(1, 6):.',`for step in range(1, 6):\n    print(step)`,'1\n2\n3\n4\n5','assert "for " in source, "Use a for loop."'],
['Backpack inventory','Meet Python lists','A list stores several items in square brackets. A loop can visit each item: <code>for item in backpack:</code>.',`backpack = ["map", "snack", "torch"]\n`,'Loop through backpack and print each item on a separate line.','Write for item in backpack: and indent print(item).',`backpack = ["map", "snack", "torch"]\nfor item in backpack:\n    print(item)`,'map\nsnack\ntorch','assert "for " in source, "Loop through the list."'],
['A reusable spell','Create a function','A function packages instructions under a name. Define one with <code>def cheer():</code>, then call it with <code>cheer()</code>.',`def cheer():\n    # Give your explorer a boost\n    pass\n\n# Call your function below\n`,'Define cheer() to print You can do this!, then call it twice.','Put print in the function, then write cheer() on two lines outside it.',`def cheer():\n    print("You can do this!")\n\ncheer()\ncheer()`,'You can do this!\nYou can do this!','assert callable(cheer), "Define a function called cheer."'],
['The final campfire','Build a tiny adventure','Bring it all together: a list, a loop, a function, and an f-string. Each skill is a tool you can now use to make your own projects.',`explorers = ["Pip", "Nova", "Ash"]\n\ndef welcome(name):\n    # Print a welcome using name\n    pass\n\n# Welcome each explorer with a loop\n`,'Define welcome(name) to print Welcome, NAME! and loop through explorers to welcome all three in order.','Inside the function use print(f"Welcome, {name}!"). Then loop through explorers and call welcome(explorer).',`explorers = ["Pip", "Nova", "Ash"]\n\ndef welcome(name):\n    print(f"Welcome, {name}!")\n\nfor explorer in explorers:\n    welcome(explorer)`,'Welcome, Pip!\nWelcome, Nova!\nWelcome, Ash!','assert callable(welcome) and "for " in source, "Use your welcome function and a loop."']
];
const groups=[['🌱','First little steps','Say hello, make things happen, and launch a rocket.'],['🎒','Pack your toolkit','Collect variables, numbers, and a little creativity.'],['🧭','Choose your adventure','Make decisions and discover a different path.'],['🏕️','Make a little magic','Repeat, collect, and build something of your own.']];
let state={done:[],drafts:{}},current=0,free=false,worker=null,timer=null;
try{const s=JSON.parse(localStorage.getItem('python-trail-v1'));if(s&&Array.isArray(s.done)&&s.drafts)state=s}catch{}
state.done=state.done.filter(n=>Number.isInteger(n)&&n>=0&&n<20);
function save(){try{localStorage.setItem('python-trail-v1',JSON.stringify(state))}catch{showInfo('<h2>Storage is full</h2><p>Your work is still here for this visit. Export your progress to keep a copy.</p>')}}
function render(){ $('xp').textContent=state.done.length*50;$('completed').textContent=`${state.done.length} / 20`;$('level').textContent=state.done.length>=20?'Python pathfinder':state.done.length>=10?'Brave builder':state.done.length>=5?'Trail explorer':'Curious beginner';$('continue').innerHTML=state.done.length?'Continue your adventure <span>↗</span>':'Start your adventure <span>↗</span>'; $('chapters').innerHTML=groups.map((g,c)=>`<section class="chapter"><button class="chapterhead" aria-expanded="true"><span class="chaptericon">${g[0]}</span><div><small>CHAPTER 0${c+1}</small><h3>${g[1]}</h3><p>${g[2]}</p></div><span class="count">${state.done.filter(n=>Math.floor(n/5)===c).length}/5 complete &nbsp;⌄</span></button><div class="quests">${lessons.slice(c*5,c*5+5).map((l,j)=>{const i=c*5+j;return `<button class="quest ${state.done.includes(i)?'done':''}" data-id="${i}"><span class="number">${state.done.includes(i)?'✓':String(i+1).padStart(2,'0')} <span style="float:right">↗</span></span><b>${l[0]}</b><small>${i%5===4?'⚑ Mini project':'◷ 5–10 min'} · 50 XP</small></button>`}).join('')}</div></section>`).join('');document.querySelectorAll('.quest').forEach(b=>b.onclick=()=>openLesson(+b.dataset.id));document.querySelectorAll('.chapterhead').forEach(b=>b.onclick=()=>{const q=b.nextElementSibling;q.hidden=!q.hidden;q.style.display=q.hidden?'none':'';b.setAttribute('aria-expanded',!q.hidden)})}
function openLesson(i,play=false){current=i;free=play;const l=lessons[i];$('lessonlabel').textContent=play?'THE OPEN PLAYGROUND':`PYTHON TRAIL / CHAPTER ${Math.floor(i/5)+1}`;$('questnum').textContent=play?'YOUR IDEAS LIVE HERE':`QUEST ${String(i+1).padStart(2,'0')} · +50 XP`;$('title').textContent=play?'What will you make?':l[0];$('explain').innerHTML=play?'<p>Try any Python code. Change a lesson, invent a story, or build a number game. Your code runs here in a separate browser worker.</p><p>For keyboard input, add one answer per line below. Each input() reads the next answer. No downloads or paid API needed.</p><textarea id="stdin" aria-label="Answers for input()" placeholder="One answer per line" style="height:90px;background:#eef2e6;color:#234d3b"></textarea>':`<p>${l[2]}</p>`;$('mission').textContent=play?'Experiment, make mistakes, and try again. That’s how coding works.':l[4];$('hint').textContent=play?'Try print(), variables, loops, lists, and functions. Standard-library Python is available; internet requests and desktop windows are not.':l[5];$('solution').hidden=play;$('answer').hidden=true;$('answer').textContent=l[6];$('editor').value=state.drafts[play?'play':i]??(play?'# Make something that makes you smile\nprint("Hello, imagination!")':l[3]);$('output').textContent='Press Run to start Python. The first run downloads the free Python runtime.';$('feedback').textContent='';$('next').hidden=true;$('run').textContent=play?'▶ Run code':'▶ Run & check';$('lesson').showModal()}
function escapeHTML(s){return s.replace(/[&<>]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[c]))}
$('continue').onclick=()=>openLesson(lessons.findIndex((_,i)=>!state.done.includes(i))<0?19:lessons.findIndex((_,i)=>!state.done.includes(i)));
$('play').onclick=()=>openLesson(0,true);$('learn').onclick=()=>$('chapters').scrollIntoView({behavior:'smooth'});$('close').onclick=()=>{halt(false);$('lesson').close()};$('lesson').addEventListener('close',()=>halt(false));$('editor').oninput=()=>{state.drafts[free?'play':current]=$('editor').value;save()};$('editor').onkeydown=e=>{if(e.key==='Tab'){e.preventDefault();const el=e.target,start=el.selectionStart;el.setRangeText('    ',start,el.selectionEnd,'end');el.dispatchEvent(new Event('input'))}if(e.ctrlKey&&e.key==='Enter'){e.preventDefault();$('run').click()}};
$('reset').onclick=()=>{$('editor').value=free?'# Your Python adventure\n':lessons[current][3];$('editor').dispatchEvent(new Event('input'))};$('solution').onclick=()=>$('answer').hidden=!$('answer').hidden;
function halt(message=true){if(worker){worker.terminate();worker=null;if(message)$('feedback').textContent='Stopped. You can edit your code and try again.'}clearTimeout(timer);$('run').disabled=false}
$('stop').onclick=()=>halt();$('run').onclick=()=>{halt(false);const source=$('editor').value,i=current,isFree=free;$('run').disabled=true;$('feedback').textContent='';$('next').hidden=true;$('output').textContent='Loading Python… First run can take a little longer.';worker=new Worker('python-worker.js');let started=false;timer=setTimeout(()=>{halt(false);$('output').textContent='Python could not load in time. Check your connection and try again.'},90000);worker.onmessage=e=>{const m=e.data;if(m.type==='ready'){started=true;clearTimeout(timer);timer=setTimeout(()=>{halt(false);$('output').textContent+='\nStopped after 8 seconds. Check for a loop that never ends.'},8000);$('output').textContent='Running…'}if(m.type==='result'){halt(false);$('output').textContent=m.output||'(No output. Use print() to show something.)';if(m.error){$('feedback').textContent='A useful clue from Python: '+m.error;return}if(isFree){$('feedback').textContent='Code ran successfully. Keep experimenting!';return}if(m.passed){if(!state.done.includes(i)){state.done.push(i);save();render()}$('feedback').textContent=i===19?'✦ You finished the trail! 1,000 XP earned. Make your own adventure in the playground.':'✓ Quest complete! +50 XP. You made that happen.';$('next').hidden=false;$('next').textContent=i===19?'Explore the playground →':'Next quest →'}else{$('feedback').textContent=m.checkError||'Almost! Compare your output with the mission. Spelling, capital letters, and line breaks matter.'}}};worker.onerror=()=>{halt(false);$('output').textContent='The Python runner could not start. Check your internet connection and try again.'};worker.postMessage({source,expected:isFree?null:lessons[i][7],check:isFree?'':lessons[i][8]||'',cases:isFree?null:lessons[i][9]||null,inputs:isFree?$('stdin').value:''})};
$('next').onclick=()=>{const i=current;halt(false);$('lesson').close();openLesson(i===19?0:i+1,i===19)};
function showInfo(html){$('infobody').innerHTML=html;$('info').showModal()}
$('guide').onclick=()=>showInfo('<div class="eyebrow">A NOTE FOR YOUR CO-PILOT</div><h2>Learn alongside them.</h2><p>This trail is designed for a beginner who can read short instructions and type. Start with 10–20 minutes together. There is no age requirement and no race to finish.</p><ol><li>Read the short explanation together.</li><li>Ask “What do you think this will do?” before running.</li><li>Let your child type, make mistakes, and change things.</li><li>Use a hint first, then talk through the worked solution.</li><li>After a quest, invent a silly variation in the playground.</li></ol><p>Every quest is unlocked. XP is awarded once per quest. Progress and code are saved only in this browser; export a backup before changing devices. This is an original learning project inspired by playful coding courses, with no subscription or paid API.</p><p>The real Python runtime loads from a public CDN, so an internet connection is needed. It supports core Python and input() with prepared answers in the playground. Files and packages created while running are temporary. Keep personal information out of practice programs.</p>');
$('badges').onclick=()=>{const n=state.done.length;showInfo(`<div class="eyebrow">YOUR EXPLORER COLLECTION</div><h2>${n*50} XP. All yours.</h2><p>Each quest earns 50 XP once. Revisit any quest whenever you like.</p>${[['🌱 First steps',5],['🎒 Trail explorer',10],['🧭 Brave builder',15],['🏕️ Python pathfinder',20]].map(([s,t])=>`<p>${n>=t?'✓':'○'} ${s} · ${Math.min(n,t)}/${t} quests</p>`).join('')}`)};
$('export').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='python-trail-progress.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
$('import').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>1000000)throw Error();const s=JSON.parse(await file.text());if(!s||!Array.isArray(s.done)||!s.drafts||typeof s.drafts!=='object'||Array.isArray(s.drafts)||!s.done.every(n=>Number.isInteger(n)&&n>=0&&n<20)||!Object.entries(s.drafts).every(([k,v])=>(k==='play'||/^([0-9]|1[0-9])$/.test(k))&&typeof v==='string'))throw Error();state.done=[...new Set([...state.done,...s.done])];Object.assign(state.drafts,s.drafts);save();render();showInfo('<h2>Welcome back, explorer.</h2><p>Your progress has been imported.</p>')}catch{showInfo('<h2>That file doesn’t look right.</h2><p>Choose a progress JSON exported from Python Trail.</p>')}e.target.value=''};render();
